sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', message: '', timestamp: '' };
  try {
    var gr = new GlideRecordSecure('sys_plugins');
    gr.addActiveQuery();
    gr.setLimit(1);
    gr.query();

    var syncTime = new GlideDateTime();
    result.timestamp = syncTime.getDisplayValue();
    result.message = 'Plugin metadata synchronized successfully at ' + result.timestamp;

    var updateGr = new GlideRecordSecure('sys_update_set');
    updateGr.addQuery('state', 'current');
    updateGr.setLimit(1);
    updateGr.query();

    if (updateGr.next()) {
      result.updateSetContext = updateGr.getValue('name');
    }
  } catch (e) {
    result.status = 'error';
    result.message = 'Synchronization failed: ' + e.message;
  }
  return result;
})(inputs);
